load accidents
population=hwydata(:,14) %Population of states %[output:09b559d5]
traffic_fatalities= hwydata(:,4) %Accidents per state %[output:48b8e920]
scatter(population,traffic_fatalities) %[output:58411805]
hold on %[output:58411805]

%Linear regression using built-in matlab functions
p=polyfit(population,traffic_fatalities,1) %finds the slope and the intercept for the first degree polynomial %[output:66463c40]
predicted_fatalities=polyval(p,population) %[output:28b7d946]
plot(population,predicted_fatalities) %[output:58411805]
xlabel("Population of State") %[output:58411805]
ylabel("Fatal Accidents Per State") %[output:58411805]
title("Linear Regression Relation Between Accidents & Population") %[output:58411805]
legend("State Data","Optimized Model","Location","southeast") %[output:58411805]

